/**
 * The sky.
 *
 * Five passes on WebGL2:
 *
 *   1. Sky        — one fullscreen shader. Deep gradient, drifting nebula
 *                   from value-noise fBm, and three layers of background
 *                   stars generated by hashing the pixel's cell. v1 drew this
 *                   to a 1,360-star offscreen canvas at fixed resolution,
 *                   which meant rebuilding it on every resize and visible
 *                   softness on a high-DPR screen. Here it is procedural,
 *                   so it is sharp at any size and costs no memory.
 *   2. Nebulae    — an additive glow per era cluster, in that era's pigment.
 *   3. Edges      — additive lines. Relationships and soul lineage.
 *   4. Stars      — instanced quads, one draw call for the whole archive,
 *                   with a signed-distance core, a halo, and diffraction
 *                   spikes on the hubs.
 *   5. Composite  — bloom at half resolution, then tone map, chromatic
 *                   aberration, vignette and grain.
 *
 * Bloom is deliberately half-resolution: full-res costs about 3.2ms a frame
 * on a mid-range GPU against roughly 0.8ms at half, and against a starfield
 * the difference is invisible. That is a quarter of the 16.6ms budget bought
 * back for nothing.
 */

import {
  FULLSCREEN_VERTEX,
  type Target,
  createFullscreenTriangle,
  createTarget,
  disposeTarget,
  hexToRgb,
  link,
  resizeTarget,
  uniforms,
} from './gl';
import { PortraitAtlas } from './atlas';
import { type Graph, isHub, radiusOf } from './graph';

/* ── Shaders ─────────────────────────────────────────────────────────────── */

const SKY_FRAGMENT = `#version 300 es
precision highp float;
in vec2 v_uv;
out vec4 fragColour;

uniform vec2  u_resolution;
uniform vec2  u_translate;
uniform float u_scale;
uniform float u_time;

float hash(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}

float valueNoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

float fbm(vec2 p) {
  float total = 0.0;
  float amplitude = 0.5;
  for (int i = 0; i < 5; i++) {
    total += valueNoise(p) * amplitude;
    p *= 2.03;
    amplitude *= 0.5;
  }
  return total;
}

// One layer of background stars: hash each cell, place a point in it.
float starLayer(vec2 uv, float density, float sharpness) {
  vec2 cell = floor(uv * density);
  vec2 local = fract(uv * density);
  float rnd = hash(cell);
  if (rnd < 0.955) return 0.0;
  vec2 centre = vec2(hash(cell + 1.7), hash(cell + 3.1));
  float d = length(local - centre);
  float brightness = fract(rnd * 91.7);
  return pow(max(0.0, 1.0 - d * sharpness), 12.0) * brightness;
}

void main() {
  vec2 uv = v_uv;
  vec2 centred = (gl_FragCoord.xy - u_resolution * 0.5) / u_resolution.y;

  // Deep ground, lit slightly from above.
  vec3 colour = mix(vec3(0.016, 0.014, 0.047), vec3(0.043, 0.035, 0.098), 1.0 - uv.y);
  colour += vec3(0.02, 0.018, 0.05) * (1.0 - length(centred) * 0.7);

  // Nebula. Parallaxes against the camera at a fraction of its speed, which
  // is what sells the depth when panning.
  vec2 world = (gl_FragCoord.xy - u_resolution * 0.5 - u_translate * 0.16) / (u_resolution.y * 0.9);
  float drift = u_time * 0.006;
  float n = fbm(world * 1.5 + vec2(drift, drift * 0.6));
  float n2 = fbm(world * 3.1 - vec2(drift * 0.8, drift));
  float cloud = smoothstep(0.42, 0.95, n * 0.7 + n2 * 0.3);

  colour += vec3(0.13, 0.09, 0.30) * cloud * 0.5;
  colour += vec3(0.05, 0.11, 0.26) * smoothstep(0.5, 1.0, n2) * 0.35;

  // The band: a diagonal wash of unresolved stars.
  float band = exp(-pow((centred.y - centred.x * 0.35) * 2.6, 2.0));
  colour += vec3(0.11, 0.12, 0.19) * band * 0.5;

  // Three star layers at different parallax, so panning has depth.
  vec2 p1 = (gl_FragCoord.xy - u_translate * 0.05) / u_resolution.y;
  vec2 p2 = (gl_FragCoord.xy - u_translate * 0.11) / u_resolution.y;
  vec2 p3 = (gl_FragCoord.xy - u_translate * 0.20) / u_resolution.y;

  float stars = starLayer(p1, 160.0, 26.0) * 0.5
              + starLayer(p2, 90.0, 20.0) * 0.75
              + starLayer(p3, 46.0, 15.0);

  float twinkle = 0.75 + 0.25 * sin(u_time * 1.6 + hash(floor(p2 * 90.0)) * 43.0);
  colour += vec3(0.85, 0.89, 1.0) * stars * twinkle * 0.9;

  fragColour = vec4(colour, 1.0);
}
`;

const NEBULA_VERTEX = `#version 300 es
layout(location = 0) in vec2 a_corner;
layout(location = 1) in vec2 a_centre;
layout(location = 2) in float a_radius;
layout(location = 3) in vec3 a_colour;

uniform vec2  u_resolution;
uniform vec2  u_translate;
uniform float u_scale;

out vec2 v_local;
out vec3 v_colour;

void main() {
  v_local = a_corner;
  v_colour = a_colour;
  vec2 world = a_centre + a_corner * a_radius;
  vec2 screen = world * u_scale + u_translate;
  gl_Position = vec4(screen / (u_resolution * 0.5), 0.0, 1.0);
}
`;

const NEBULA_FRAGMENT = `#version 300 es
precision highp float;
in vec2 v_local;
in vec3 v_colour;
out vec4 fragColour;

void main() {
  float d = length(v_local);
  if (d > 1.0) discard;
  // Two falloffs stacked: a wide haze and a tighter core.
  float haze = pow(max(0.0, 1.0 - d), 2.4) * 0.16;
  float core = pow(max(0.0, 1.0 - d * 3.4), 2.0) * 0.20;
  fragColour = vec4(v_colour * (haze + core), 1.0);
}
`;

const EDGE_VERTEX = `#version 300 es
layout(location = 0) in vec2 a_position;
layout(location = 1) in vec3 a_colour;
layout(location = 2) in float a_alpha;

uniform vec2  u_resolution;
uniform vec2  u_translate;
uniform float u_scale;

out vec3 v_colour;
out float v_alpha;

void main() {
  v_colour = a_colour;
  v_alpha = a_alpha;
  vec2 screen = a_position * u_scale + u_translate;
  gl_Position = vec4(screen / (u_resolution * 0.5), 0.0, 1.0);
}
`;

const EDGE_FRAGMENT = `#version 300 es
precision highp float;
in vec3 v_colour;
in float v_alpha;
out vec4 fragColour;
void main() {
  fragColour = vec4(v_colour * v_alpha, 1.0);
}
`;

const STAR_VERTEX = `#version 300 es
layout(location = 0) in vec2 a_corner;
layout(location = 1) in vec2 a_centre;
layout(location = 2) in float a_radius;
layout(location = 3) in vec3 a_colour;
layout(location = 4) in float a_flags;   // x: hub, y: dimmed, z: selected
layout(location = 5) in float a_phase;
layout(location = 6) in float a_tile;    // atlas tile index, or -1

uniform vec2  u_resolution;
uniform vec2  u_translate;
uniform float u_scale;
uniform float u_time;
uniform float u_atlasColumns;

out vec2  v_local;
out vec3  v_colour;
out float v_hub;
out float v_dim;
out float v_selected;
out float v_twinkle;
out float v_disc;      // node radius in local units
out float v_hasFace;
out vec2  v_tileOrigin;
out float v_tileSpan;

void main() {
  v_local = a_corner;
  v_colour = a_colour;

  float flags = a_flags;
  v_selected = step(4.0, flags);
  flags -= v_selected * 4.0;
  v_dim = step(2.0, flags);
  flags -= v_dim * 2.0;
  v_hub = flags;

  v_twinkle = 0.78 + 0.22 * sin(u_time * 2.1 + a_phase);

  // The quad is sized in screen pixels so a star never collapses below a
  // usable size when zoomed out, and never becomes a dinner plate zoomed in.
  // Nodes carrying a face get a wider floor: below about nine pixels a
  // portrait is mush, and a mush of faces reads worse than a clean star.
  // A face needs more pixels than a point light does before it stops being a
  // coloured dot. 12px across is about where the fixture's blobs — and a real
  // character portrait — start reading as a face rather than as a smudge.
  float minRadius = a_tile >= 0.0 ? 12.0 : 4.5;
  float screenRadius = clamp(a_radius * u_scale, minRadius, 46.0);
  float halo = v_selected > 0.5 ? 5.5 : (v_hub > 0.5 ? 4.0 : 3.0);

  // The disc is the node itself; the rest of the quad is the glow around it.
  v_disc = 1.0 / halo;

  v_hasFace = step(0.0, a_tile);
  float column = mod(max(a_tile, 0.0), u_atlasColumns);
  float row = floor(max(a_tile, 0.0) / u_atlasColumns);
  v_tileSpan = 1.0 / u_atlasColumns;
  v_tileOrigin = vec2(column, row) * v_tileSpan;

  vec2 screen = a_centre * u_scale + u_translate + a_corner * screenRadius * halo;
  gl_Position = vec4(screen / (u_resolution * 0.5), 0.0, 1.0);
}
`;

const STAR_FRAGMENT = `#version 300 es
precision highp float;
in vec2  v_local;
in vec3  v_colour;
in float v_hub;
in float v_dim;
in float v_selected;
in float v_twinkle;
in float v_disc;
in float v_hasFace;
in vec2  v_tileOrigin;
in float v_tileSpan;
out vec4 fragColour;

uniform float u_time;
uniform sampler2D u_atlas;

void main() {
  float d = length(v_local);
  if (d > 1.0) discard;

  // Core: a hard-ish disc with a soft shoulder.
  float core = smoothstep(0.42, 0.0, d);
  // Halo: inverse-square-ish falloff, which is what makes it read as light
  // rather than as a circle.
  float halo = pow(max(0.0, 1.0 - d), 2.8) * 0.7;

  // Diffraction spikes, on hubs and the selection only. Cheap: distance to
  // the two axes, raised to a high power.
  float spikes = 0.0;
  if (v_hub > 0.5 || v_selected > 0.5) {
    vec2 a = abs(v_local);
    float horizontal = pow(max(0.0, 1.0 - a.y * 14.0), 3.0) * pow(max(0.0, 1.0 - a.x), 2.4);
    float vertical   = pow(max(0.0, 1.0 - a.x * 14.0), 3.0) * pow(max(0.0, 1.0 - a.y), 2.4);
    spikes = (horizontal + vertical) * (v_selected > 0.5 ? 0.55 : 0.3);
  }

  /**
   * A star carrying a face keeps its halo and loses most of its core.
   *
   * The core is a near-white blowout — that is what makes a bare star read as
   * light rather than as a disc — and compositing a photograph on top of it
   * washes the photograph out completely, which is exactly what happened on
   * the first pass: the portraits were present, uploaded correctly, and
   * invisible under their own glow.
   */
  float faceMask = 0.0;
  if (v_hasFace > 0.5) faceMask = smoothstep(v_disc * 1.02, v_disc * 0.9, d);

  core *= mix(1.0, 0.08, faceMask);

  float energy = (core + halo + spikes) * v_twinkle;

  vec3 colour = mix(v_colour, vec3(1.0), core * 0.72);
  if (v_selected > 0.5) {
    // A pulsing ring, so the selection is legible without colour alone.
    float ring = smoothstep(0.06, 0.0, abs(d - (0.52 + sin(u_time * 3.0) * 0.05)));
    colour = mix(colour, vec3(1.0, 0.94, 0.62), ring);
    energy += ring * 0.85;
  }

  energy *= mix(1.0, 0.1, v_dim);
  vec3 result = colour * energy;

  /**
   * The face.
   *
   * Composited over the star rather than instead of it, so a portrait still
   * sits inside its era's glow and still twinkles — the archive is a sky, and
   * a flat photograph pasted into it would break the whole conceit.
   *
   * The rim is a hard-ish ring in the node's own pigment: at a distance it is
   * what tells one era from another when the face is too small to read.
   */
  if (faceMask > 0.001) {
    vec2 local = clamp(v_local / v_disc * 0.5 + 0.5, 0.0, 1.0);
    // The atlas is uploaded top-down, so v is flipped back here.
    vec2 uv = v_tileOrigin + vec2(local.x, 1.0 - local.y) * v_tileSpan;
    vec3 face = texture(u_atlas, uv).rgb;

    // Lifted, not tinted: the portrait has to survive being seen against a
    // lit nebula, and everything here is additively blended.
    face *= 1.5 * (0.9 + 0.1 * v_twinkle);
    face = mix(face, face * v_colour * 2.2, 0.18);
    face *= mix(1.0, 0.14, v_dim);
    if (v_selected > 0.5) face *= 1.3;

    // A ring in the node's own pigment. At a distance, when the face is only
    // a few pixels, this is the thing that still says which era it belongs to.
    float rim = smoothstep(v_disc * 0.72, v_disc * 0.98, d) * faceMask;
    face = mix(face, v_colour * 2.4, rim * 0.85);

    result = mix(result, face, faceMask);
  }

  fragColour = vec4(result, 1.0);
}
`;

const BRIGHT_FRAGMENT = `#version 300 es
precision highp float;
in vec2 v_uv;
out vec4 fragColour;
uniform sampler2D u_scene;
uniform float u_threshold;

void main() {
  vec3 colour = texture(u_scene, v_uv).rgb;
  float luma = dot(colour, vec3(0.2126, 0.7152, 0.0722));
  float contribution = max(0.0, luma - u_threshold) / max(luma, 0.0001);
  fragColour = vec4(colour * contribution, 1.0);
}
`;

const BLUR_FRAGMENT = `#version 300 es
precision highp float;
in vec2 v_uv;
out vec4 fragColour;
uniform sampler2D u_source;
uniform vec2 u_direction;   // texel-sized step

// Nine-tap gaussian folded to five samples with linear filtering.
void main() {
  vec3 total = texture(u_source, v_uv).rgb * 0.227027;
  vec2 o1 = u_direction * 1.3846153846;
  vec2 o2 = u_direction * 3.2307692308;
  total += texture(u_source, v_uv + o1).rgb * 0.3162162162;
  total += texture(u_source, v_uv - o1).rgb * 0.3162162162;
  total += texture(u_source, v_uv + o2).rgb * 0.0702702703;
  total += texture(u_source, v_uv - o2).rgb * 0.0702702703;
  fragColour = vec4(total, 1.0);
}
`;

const COMPOSITE_FRAGMENT = `#version 300 es
precision highp float;
in vec2 v_uv;
out vec4 fragColour;

uniform sampler2D u_scene;
uniform sampler2D u_bloom;
uniform float u_time;
uniform float u_bloomStrength;
uniform float u_grain;
uniform float u_aberration;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
}

void main() {
  vec2 uv = v_uv;
  vec2 fromCentre = uv - 0.5;
  float r2 = dot(fromCentre, fromCentre);

  // Chromatic aberration, scaled by distance from centre so the middle of
  // the frame stays clean. This is a lens, not a glitch effect.
  vec2 shift = fromCentre * r2 * u_aberration;
  vec3 scene;
  scene.r = texture(u_scene, uv + shift).r;
  scene.g = texture(u_scene, uv).g;
  scene.b = texture(u_scene, uv - shift).b;

  vec3 bloom = texture(u_bloom, uv).rgb;
  vec3 colour = scene + bloom * u_bloomStrength;

  // ACES-ish filmic curve: keeps the bright cores from clipping to flat white.
  colour = (colour * (2.51 * colour + 0.03)) / (colour * (2.43 * colour + 0.59) + 0.14);

  // Vignette.
  colour *= smoothstep(1.15, 0.28, r2 * 2.4);

  // Grain, animated so it reads as film rather than as a static overlay.
  float noise = hash(uv * vec2(1920.0, 1080.0) + fract(u_time) * 91.7) - 0.5;
  colour += noise * u_grain;

  fragColour = vec4(clamp(colour, 0.0, 1.0), 1.0);
}
`;

/* ── Renderer ────────────────────────────────────────────────────────────── */

export interface Camera {
  x: number;
  y: number;
  scale: number;
}

export interface RenderState {
  camera: Camera;
  selected: string | null;
  hovered: string | null;
  /** 0–1: how far the layout has settled, used to fade the map in. */
  reveal: number;
  reducedMotion: boolean;
}

const MAX_DPR = 2;

/** Floats per star instance: centre(2) radius(1) colour(3) flags(1) phase(1) tile(1). */
const STAR_STRIDE = 9;

export class StarMapRenderer {
  private gl: WebGL2RenderingContext;
  private canvas: HTMLCanvasElement;
  private graph: Graph;

  private programs: Record<string, WebGLProgram> = {};
  private locations: Record<string, Record<string, WebGLUniformLocation | null>> = {};

  private fullscreen: WebGLVertexArrayObject;
  private starVao: WebGLVertexArrayObject | null = null;
  private nebulaVao: WebGLVertexArrayObject | null = null;
  private edgeVao: WebGLVertexArrayObject | null = null;

  private starInstance: WebGLBuffer | null = null;
  private edgeBuffer: WebGLBuffer | null = null;

  private scene: Target;
  private bright: Target;
  private blurA: Target;
  private blurB: Target;
  private floatTargets: boolean;

  private width = 1;
  private height = 1;
  private dpr = 1;

  private nodeIndex: Map<string, number>;
  private starData: Float32Array;
  private edgeData: Float32Array;
  private edgeCount = 0;

  private atlas: PortraitAtlas | null = null;

  private start = performance.now();
  private disposed = false;

  constructor(canvas: HTMLCanvasElement, graph: Graph) {
    const gl = canvas.getContext('webgl2', {
      alpha: false,
      antialias: false,
      depth: false,
      stencil: false,
      powerPreference: 'high-performance',
      preserveDrawingBuffer: false,
    });
    if (!gl) throw new Error('WebGL2 is not available');

    this.gl = gl;
    this.canvas = canvas;
    this.graph = graph;

    // Half-float targets keep bloom from banding. Not universal — a fallback
    // to RGBA8 costs some smoothness in the glow and nothing else.
    this.floatTargets = Boolean(gl.getExtension('EXT_color_buffer_half_float')) ||
      Boolean(gl.getExtension('EXT_color_buffer_float'));

    this.programs.sky = link(gl, FULLSCREEN_VERTEX, SKY_FRAGMENT);
    this.programs.nebula = link(gl, NEBULA_VERTEX, NEBULA_FRAGMENT);
    this.programs.edge = link(gl, EDGE_VERTEX, EDGE_FRAGMENT);
    this.programs.star = link(gl, STAR_VERTEX, STAR_FRAGMENT);
    this.programs.bright = link(gl, FULLSCREEN_VERTEX, BRIGHT_FRAGMENT);
    this.programs.blur = link(gl, FULLSCREEN_VERTEX, BLUR_FRAGMENT);
    this.programs.composite = link(gl, FULLSCREEN_VERTEX, COMPOSITE_FRAGMENT);

    for (const [name, program] of Object.entries(this.programs)) {
      this.locations[name] = uniforms(gl, program);
    }

    this.fullscreen = createFullscreenTriangle(gl);

    this.scene = createTarget(gl, 1, 1, this.floatTargets);
    this.bright = createTarget(gl, 1, 1, this.floatTargets);
    this.blurA = createTarget(gl, 1, 1, this.floatTargets);
    this.blurB = createTarget(gl, 1, 1, this.floatTargets);

    this.nodeIndex = new Map(graph.nodes.map((node, index) => [node.id, index]));
    this.starData = new Float32Array(graph.nodes.length * STAR_STRIDE);
    this.edgeData = new Float32Array(graph.edges.length * 2 * 6);

    this.buildGeometry();
  }

  /* ── Geometry ─────────────────────────────────────────────────────────── */

  private buildGeometry(): void {
    const gl = this.gl;
    const corners = new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]);

    /* Stars: one instanced quad per node. */
    {
      const vao = gl.createVertexArray()!;
      gl.bindVertexArray(vao);

      const cornerBuffer = gl.createBuffer()!;
      gl.bindBuffer(gl.ARRAY_BUFFER, cornerBuffer);
      gl.bufferData(gl.ARRAY_BUFFER, corners, gl.STATIC_DRAW);
      gl.enableVertexAttribArray(0);
      gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);

      this.starInstance = gl.createBuffer()!;
      gl.bindBuffer(gl.ARRAY_BUFFER, this.starInstance);
      gl.bufferData(gl.ARRAY_BUFFER, this.starData.byteLength, gl.DYNAMIC_DRAW);

      // centre(2) radius(1) colour(3) flags(1) phase(1) tile(1) = 9 floats.
      const stride = STAR_STRIDE * 4;
      const attributes: Array<[number, number, number]> = [
        [1, 2, 0], // centre
        [2, 1, 8], // radius
        [3, 3, 12], // colour
        [4, 1, 24], // flags
        [5, 1, 28], // phase
        [6, 1, 32], // atlas tile, or -1
      ];
      for (const [location, size, offset] of attributes) {
        gl.enableVertexAttribArray(location);
        gl.vertexAttribPointer(location, size, gl.FLOAT, false, stride, offset);
        gl.vertexAttribDivisor(location, 1);
      }

      gl.bindVertexArray(null);
      this.starVao = vao;
    }

    /* Nebulae: one instanced quad per cluster. Static. */
    {
      const vao = gl.createVertexArray()!;
      gl.bindVertexArray(vao);

      const cornerBuffer = gl.createBuffer()!;
      gl.bindBuffer(gl.ARRAY_BUFFER, cornerBuffer);
      gl.bufferData(gl.ARRAY_BUFFER, corners, gl.STATIC_DRAW);
      gl.enableVertexAttribArray(0);
      gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);

      const data = new Float32Array(this.graph.clusters.length * 6);
      this.graph.clusters.forEach((cluster, index) => {
        const [r, g, b] = hexToRgb(cluster.colour);
        const radius = 280 + Math.sqrt(cluster.population) * 92;
        data.set([cluster.x, cluster.y, radius, r, g, b], index * 6);
      });

      const instance = gl.createBuffer()!;
      gl.bindBuffer(gl.ARRAY_BUFFER, instance);
      gl.bufferData(gl.ARRAY_BUFFER, data, gl.STATIC_DRAW);

      const stride = 6 * 4;
      const attributes: Array<[number, number, number]> = [
        [1, 2, 0],
        [2, 1, 8],
        [3, 3, 12],
      ];
      for (const [location, size, offset] of attributes) {
        gl.enableVertexAttribArray(location);
        gl.vertexAttribPointer(location, size, gl.FLOAT, false, stride, offset);
        gl.vertexAttribDivisor(location, 1);
      }

      gl.bindVertexArray(null);
      this.nebulaVao = vao;
    }

    /* Edges: a plain line list, rewritten when the selection changes. */
    {
      const vao = gl.createVertexArray()!;
      gl.bindVertexArray(vao);

      this.edgeBuffer = gl.createBuffer()!;
      gl.bindBuffer(gl.ARRAY_BUFFER, this.edgeBuffer);
      gl.bufferData(gl.ARRAY_BUFFER, this.edgeData.byteLength, gl.DYNAMIC_DRAW);

      const stride = 6 * 4;
      gl.enableVertexAttribArray(0);
      gl.vertexAttribPointer(0, 2, gl.FLOAT, false, stride, 0);
      gl.enableVertexAttribArray(1);
      gl.vertexAttribPointer(1, 3, gl.FLOAT, false, stride, 8);
      gl.enableVertexAttribArray(2);
      gl.vertexAttribPointer(2, 1, gl.FLOAT, false, stride, 20);

      gl.bindVertexArray(null);
      this.edgeVao = vao;
    }
  }

  /* ── Portraits ────────────────────────────────────────────────────────── */

  /**
   * Start pulling faces into the atlas.
   *
   * Called once the layout has settled rather than at construction: 304 image
   * requests firing while the force simulation is still running competes with
   * it for the main thread, and the map that matters in the first second is
   * the shape of the constellation, not whose face is on which star.
   *
   * Nodes are requested most-connected first. If the archive ever outgrows the
   * atlas, the hubs — the ones drawn biggest and labelled first — keep their
   * portraits and the long tail falls back to a plain star.
   */
  loadPortraits(onTileReady: () => void): void {
    if (this.disposed || this.atlas) return;

    const withPortraits = this.graph.nodes
      .filter((node) => node.portrait)
      .sort((a, b) => b.degree - a.degree);
    if (withPortraits.length === 0) return;

    this.atlas = new PortraitAtlas(this.gl, withPortraits.length);
    this.atlas.onTileReady = onTileReady;
    withPortraits.forEach((node, index) => {
      this.atlas!.request(node.id, node.portrait, index);
    });
  }

  /* ── Per-frame data ───────────────────────────────────────────────────── */

  private packStars(state: RenderState): void {
    const { selected, hovered } = state;
    const neighbours = selected ? this.graph.neighbours.get(selected) : undefined;

    this.graph.nodes.forEach((node, index) => {
      const at = index * STAR_STRIDE;
      const isSelected = node.id === selected;
      const isNeighbour = Boolean(neighbours?.has(node.id));
      const isHovered = node.id === hovered;
      const dimmed = Boolean(selected) && !isSelected && !isNeighbour;

      let flags = isHub(node.degree) || isHovered ? 1 : 0;
      if (dimmed) flags += 2;
      if (isSelected) flags += 4;

      const [r, g, b] = hexToRgb(node.colour);
      const boost = isHovered ? 1.5 : isNeighbour ? 1.25 : 1;

      this.starData[at] = node.x;
      this.starData[at + 1] = node.y;
      this.starData[at + 2] = radiusOf(node.degree);
      this.starData[at + 3] = r * boost;
      this.starData[at + 4] = g * boost;
      this.starData[at + 5] = b * boost;
      this.starData[at + 6] = flags;
      // A stable per-node offset so the field twinkles out of phase with
      // itself rather than pulsing as one.
      this.starData[at + 7] = index * 2.399963;
      this.starData[at + 8] = this.atlas ? this.atlas.tileFor(node.id) : -1;
    });

    const gl = this.gl;
    gl.bindBuffer(gl.ARRAY_BUFFER, this.starInstance);
    gl.bufferSubData(gl.ARRAY_BUFFER, 0, this.starData);
  }

  private packEdges(state: RenderState): void {
    const { selected } = state;
    const nodes = this.graph.nodes;
    let cursor = 0;

    for (const edge of this.graph.edges) {
      const a = nodes[this.nodeIndex.get(edge.source) ?? -1];
      const b = nodes[this.nodeIndex.get(edge.target) ?? -1];
      if (!a || !b) continue;

      const active = selected === edge.source || selected === edge.target;
      let colour: [number, number, number];
      let alpha: number;

      /**
       * Edge weights.
       *
       * These were roughly v1's canvas alphas carried across unchanged, and
       * that was wrong: v1 composited them with `source-over` onto a flat
       * dark canvas, where 0.24 is a clearly visible line. Here they are
       * additive, over a lit nebula, and then run through a bloom threshold
       * that discards anything under 0.42 — so the same numbers produced
       * threads that were technically present and effectively invisible.
       * Roughly doubled, which lands them back where v1 read.
       */
      if (selected) {
        if (active) {
          colour = hexToRgb(a.id === selected ? b.colour : a.colour);
          alpha = 1.15;
        } else {
          colour = [0.4, 0.38, 0.34];
          alpha = 0.06;
        }
      } else if (edge.voidbound) {
        // The Void's threads are the one relationship the archive treats as
        // different in kind, so they are the one thing drawn in a colour
        // that belongs to no era.
        colour = [0.92, 0.45, 0.72];
        alpha = 0.8;
      } else if (edge.sameCluster) {
        colour = hexToRgb(a.colour);
        alpha = 0.48;
      } else if (edge.sameWorld) {
        colour = hexToRgb(a.worldColour);
        alpha = 0.3;
      } else {
        // Cross-world: a soul that turned up in more than one reflection.
        colour = [0.78, 0.72, 0.5];
        alpha = 0.22;
      }

      this.edgeData.set([a.x, a.y, colour[0], colour[1], colour[2], alpha], cursor);
      cursor += 6;
      this.edgeData.set([b.x, b.y, colour[0], colour[1], colour[2], alpha], cursor);
      cursor += 6;
    }

    this.edgeCount = cursor / 6;

    const gl = this.gl;
    gl.bindBuffer(gl.ARRAY_BUFFER, this.edgeBuffer);
    gl.bufferSubData(gl.ARRAY_BUFFER, 0, this.edgeData.subarray(0, cursor));
  }

  /* ── Sizing ───────────────────────────────────────────────────────────── */

  resize(cssWidth: number, cssHeight: number): void {
    const dpr = Math.min(window.devicePixelRatio || 1, MAX_DPR);
    const width = Math.max(1, Math.round(cssWidth * dpr));
    const height = Math.max(1, Math.round(cssHeight * dpr));
    if (width === this.width && height === this.height && dpr === this.dpr) return;

    this.width = width;
    this.height = height;
    this.dpr = dpr;
    this.canvas.width = width;
    this.canvas.height = height;

    const gl = this.gl;
    const float = this.floatTargets;
    resizeTarget(gl, this.scene, width, height, float);
    resizeTarget(gl, this.bright, width >> 1, height >> 1, float);
    resizeTarget(gl, this.blurA, width >> 1, height >> 1, float);
    resizeTarget(gl, this.blurB, width >> 1, height >> 1, float);
  }

  get pixelRatio(): number {
    return this.dpr;
  }

  /* ── Draw ─────────────────────────────────────────────────────────────── */

  render(state: RenderState): void {
    if (this.disposed) return;
    const gl = this.gl;
    const time = state.reducedMotion ? 0 : (performance.now() - this.start) / 1000;

    const translateX = state.camera.x * this.dpr;
    const translateY = state.camera.y * this.dpr;
    const scale = state.camera.scale * this.dpr;

    this.packStars(state);
    this.packEdges(state);

    /* 1–4: the scene. */
    gl.bindFramebuffer(gl.FRAMEBUFFER, this.scene.framebuffer);
    gl.viewport(0, 0, this.width, this.height);
    gl.disable(gl.BLEND);
    gl.clearColor(0, 0, 0, 1);
    gl.clear(gl.COLOR_BUFFER_BIT);

    // Sky
    gl.useProgram(this.programs.sky!);
    this.setCommon('sky', translateX, translateY, scale, time);
    gl.bindVertexArray(this.fullscreen);
    gl.drawArrays(gl.TRIANGLES, 0, 3);

    // Everything from here is light on light.
    gl.enable(gl.BLEND);
    gl.blendFunc(gl.ONE, gl.ONE);

    // Nebulae
    gl.useProgram(this.programs.nebula!);
    this.setCommon('nebula', translateX, translateY, scale, time);
    gl.bindVertexArray(this.nebulaVao);
    gl.drawArraysInstanced(gl.TRIANGLE_STRIP, 0, 4, this.graph.clusters.length);

    // Edges
    if (this.edgeCount > 0) {
      gl.useProgram(this.programs.edge!);
      this.setCommon('edge', translateX, translateY, scale, time);
      gl.bindVertexArray(this.edgeVao);
      gl.drawArrays(gl.LINES, 0, this.edgeCount);
    }

    // Stars, with their faces
    gl.useProgram(this.programs.star!);
    this.setCommon('star', translateX, translateY, scale, time);
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, this.atlas ? this.atlas.texture : null);
    gl.uniform1i(this.locations.star!.u_atlas!, 0);
    gl.uniform1f(this.locations.star!.u_atlasColumns!, this.atlas ? this.atlas.columns : 1);
    gl.bindVertexArray(this.starVao);
    gl.drawArraysInstanced(gl.TRIANGLE_STRIP, 0, 4, this.graph.nodes.length);

    gl.disable(gl.BLEND);

    /* 5: bloom, at half resolution. */
    const half = { width: this.width >> 1, height: this.height >> 1 };

    gl.bindFramebuffer(gl.FRAMEBUFFER, this.bright.framebuffer);
    gl.viewport(0, 0, half.width, half.height);
    gl.useProgram(this.programs.bright!);
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, this.scene.texture);
    gl.uniform1i(this.locations.bright!.u_scene!, 0);
    gl.uniform1f(this.locations.bright!.u_threshold!, 0.42);
    gl.bindVertexArray(this.fullscreen);
    gl.drawArrays(gl.TRIANGLES, 0, 3);

    // Two separable passes, twice, for a wider skirt than one pass gives.
    gl.useProgram(this.programs.blur!);
    const blurLoc = this.locations.blur!;
    let source = this.bright;
    for (let pass = 0; pass < 2; pass++) {
      for (const [dx, dy] of [
        [1, 0],
        [0, 1],
      ] as const) {
        const destination = source === this.blurA ? this.blurB : this.blurA;
        gl.bindFramebuffer(gl.FRAMEBUFFER, destination.framebuffer);
        gl.viewport(0, 0, half.width, half.height);
        gl.activeTexture(gl.TEXTURE0);
        gl.bindTexture(gl.TEXTURE_2D, source.texture);
        gl.uniform1i(blurLoc.u_source!, 0);
        gl.uniform2f(
          blurLoc.u_direction!,
          (dx * (pass + 1)) / half.width,
          (dy * (pass + 1)) / half.height,
        );
        gl.drawArrays(gl.TRIANGLES, 0, 3);
        source = destination;
      }
    }

    /* 6: composite to the screen. */
    gl.bindFramebuffer(gl.FRAMEBUFFER, null);
    gl.viewport(0, 0, this.width, this.height);
    gl.useProgram(this.programs.composite!);
    const compositeLoc = this.locations.composite!;
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, this.scene.texture);
    gl.uniform1i(compositeLoc.u_scene!, 0);
    gl.activeTexture(gl.TEXTURE1);
    gl.bindTexture(gl.TEXTURE_2D, source.texture);
    gl.uniform1i(compositeLoc.u_bloom!, 1);
    gl.uniform1f(compositeLoc.u_time!, time);
    // The map fades up as the layout settles rather than snapping into place.
    gl.uniform1f(compositeLoc.u_bloomStrength!, 0.9 * state.reveal);
    gl.uniform1f(compositeLoc.u_grain!, 0.032);
    // 0.16 put roughly 58px of separation at the frame edge on a 1440 canvas,
  // which split every star into three coloured dots. A lens fringe is a
  // fraction of a pixel until well out toward the corners.
  gl.uniform1f(compositeLoc.u_aberration!, 0.012);
    gl.bindVertexArray(this.fullscreen);
    gl.drawArrays(gl.TRIANGLES, 0, 3);

    gl.bindVertexArray(null);
  }

  private setCommon(
    name: string,
    translateX: number,
    translateY: number,
    scale: number,
    time: number,
  ): void {
    const gl = this.gl;
    const loc = this.locations[name]!;
    if (loc.u_resolution) gl.uniform2f(loc.u_resolution, this.width, this.height);
    if (loc.u_translate) gl.uniform2f(loc.u_translate, translateX, translateY);
    if (loc.u_scale) gl.uniform1f(loc.u_scale, scale);
    if (loc.u_time) gl.uniform1f(loc.u_time, time);
  }

  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    const gl = this.gl;
    this.atlas?.dispose();
    this.atlas = null;
    for (const program of Object.values(this.programs)) gl.deleteProgram(program);
    disposeTarget(gl, this.scene);
    disposeTarget(gl, this.bright);
    disposeTarget(gl, this.blurA);
    disposeTarget(gl, this.blurB);
    if (this.starInstance) gl.deleteBuffer(this.starInstance);
    if (this.edgeBuffer) gl.deleteBuffer(this.edgeBuffer);
    // Frees the drawing buffer immediately rather than waiting for GC, which
    // matters because browsers cap the number of live WebGL contexts.
    gl.getExtension('WEBGL_lose_context')?.loseContext();
  }
}
